@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 220 14% 96%;
    --foreground: 224 71% 4%;
    --card: 0 0% 100%;
    --card-foreground: 224 71% 4%;
    --popover: 0 0% 100%;
    --popover-foreground: 224 71% 4%;
    --primary: 215 89% 45%;
    --primary-foreground: 210 20% 98%;
    --secondary: 220 14% 90%;
    --secondary-foreground: 220 9% 15%;
    --muted: 220 14% 90%;
    --muted-foreground: 220 9% 45%;
    --accent: 199 89% 48%;
    --accent-foreground: 224 71% 4%;
    --destructive: 0 84% 60%;
    --destructive-foreground: 210 20% 98%;
    --border: 220 13% 85%;
    --input: 220 13% 85%;
    --ring: 215 89% 45%;
    --radius: 0.375rem;
  }

  .dark {
    --background: 222 47% 6%;
    --foreground: 210 40% 98%;
    --card: 222 47% 8%;
    --card-foreground: 210 40% 98%;
    --popover: 222 47% 8%;
    --popover-foreground: 210 40% 98%;
    --primary: 199 89% 48%;
    --primary-foreground: 222 47% 6%;
    --secondary: 217 33% 15%;
    --secondary-foreground: 210 40% 98%;
    --muted: 217 33% 14%;
    --muted-foreground: 215 20% 65%;
    --accent: 199 89% 48%;
    --accent-foreground: 222 47% 6%;
    --destructive: 350 89% 60%;
    --destructive-foreground: 210 40% 98%;
    --border: 217 33% 18%;
    --input: 217 33% 18%;
    --ring: 199 89% 48%;
  }
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: hsl(var(--background));
  color: hsl(var(--foreground));
  overflow-x: hidden;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
}

/* Tactical grid pattern */
.tactical-grid {
  background-image: radial-gradient(rgba(0, 229, 255, 0.08) 1px, transparent 0);
  background-size: 24px 24px;
  background-position: -19px -19px;
}

.tactical-grid-dense {
  background-size: 20px 20px;
  background-image: 
    linear-gradient(to right, rgba(30, 41, 59, 0.4) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(30, 41, 59, 0.4) 1px, transparent 1px);
}

.light .tactical-grid-dense {
  background-image: 
    linear-gradient(to right, rgba(226, 232, 240, 0.8) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(226, 232, 240, 0.8) 1px, transparent 1px);
}

/* Custom scrollbars for dense intelligence panels */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.3);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(100, 116, 139, 0.6);
}

/* Monospace telemetry */
.font-mono-numbers {
  font-variant-numeric: tabular-nums;
}

/* Scanline / crosshair aesthetic */
.scanline {
  background: linear-gradient(
    to bottom,
    rgba(255,255,255,0),
    rgba(255,255,255,0) 50%,
    rgba(0, 229, 255, 0.02) 50%,
    rgba(0, 229, 255, 0.02)
  );
  background-size: 100% 4px;
}

