import React, { useState, useMemo } from 'react'
import { 
  ChevronUp, 
  ChevronDown, 
  ChevronsUpDown, 
  Search, 
  ChevronLeft, 
  ChevronRight 
} from 'lucide-react'
import { cn } from '../../lib/utils'
import { Input } from '../ui/input'
import { Button } from '../ui/button'

export interface Column<T> {
  header: string
  accessorKey?: keyof T
  cell?: (row: T) => React.ReactNode
  sortable?: boolean
  className?: string
}

export interface DataTableProps<T> {
  data: T[]
  columns: Column<T>[]
  searchPlaceholder?: string
  searchKey?: keyof T
  pageSize?: number
  onRowClick?: (row: T) => void
  actions?: React.ReactNode
}

export function DataTable<T extends Record<string, any>>({
  data,
  columns,
  searchPlaceholder = 'Filter records...',
  searchKey,
  pageSize = 8,
  onRowClick,
  actions
}: DataTableProps<T>) {
  const [searchTerm, setSearchTerm] = useState('')
  const [sortKey, setSortKey] = useState<keyof T | null>(null)
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc')
  const [currentPage, setCurrentPage] = useState(1)

  // Filter
  const filteredData = useMemo(() => {
    if (!searchTerm.trim()) return data
    return data.filter((item) => {
      if (searchKey) {
        const val = String(item[searchKey] || '')
        return val.toLowerCase().includes(searchTerm.toLowerCase())
      }
      return Object.values(item).some((val) =>
        String(val).toLowerCase().includes(searchTerm.toLowerCase())
      )
    })
  }, [data, searchTerm, searchKey])

  // Sort
  const sortedData = useMemo(() => {
    if (!sortKey) return filteredData
    return [...filteredData].sort((a, b) => {
      const aVal = a[sortKey]
      const bVal = b[sortKey]
      if (aVal === bVal) return 0
      if (aVal === undefined || aVal === null) return 1
      if (bVal === undefined || bVal === null) return -1
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal
      }
      return sortDirection === 'asc'
        ? String(aVal).localeCompare(String(bVal))
        : String(bVal).localeCompare(String(aVal))
    })
  }, [filteredData, sortKey, sortDirection])

  // Pagination
  const totalPages = Math.ceil(sortedData.length / pageSize) || 1
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize
    return sortedData.slice(start, start + pageSize)
  }, [sortedData, currentPage, pageSize])

  const handleSort = (key?: keyof T) => {
    if (!key) return
    if (sortKey === key) {
      if (sortDirection === 'asc') setSortDirection('desc')
      else {
        setSortKey(null)
        setSortDirection('asc')
      }
    } else {
      setSortKey(key)
      setSortDirection('asc')
    }
  }

  return (
    <div className="space-y-3 font-mono">
      {/* Controls Bar */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
        <div className="relative w-full sm:w-72">
          <Search className="absolute left-2.5 top-2.5 h-3.5 w-3.5 text-slate-400" />
          <Input
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value)
              setCurrentPage(1)
            }}
            placeholder={searchPlaceholder}
            className="pl-8 text-xs bg-slate-900/90 border-slate-700"
          />
        </div>
        {actions && <div className="flex items-center space-x-2">{actions}</div>}
      </div>

      {/* Table Container */}
      <div className="overflow-x-auto rounded-sm border border-slate-800 bg-[#0c121e]/90 shadow-md">
        <table className="w-full text-left text-xs border-collapse">
          <thead>
            <tr className="border-b border-slate-800 bg-slate-900/90 text-slate-400 select-none uppercase tracking-wider text-[10px]">
              {columns.map((col, index) => (
                <th
                  key={index}
                  onClick={() => col.sortable && handleSort(col.accessorKey)}
                  className={cn(
                    'p-3 font-semibold',
                    col.sortable && 'cursor-pointer hover:text-cyan-300 hover:bg-slate-800/50 transition-colors',
                    col.className
                  )}
                >
                  <div className="flex items-center space-x-1">
                    <span>{col.header}</span>
                    {col.sortable && (
                      <span className="text-slate-400">
                        {sortKey === col.accessorKey ? (
                          sortDirection === 'asc' ? (
                            <ChevronUp className="h-3 w-3 text-cyan-400" />
                          ) : (
                            <ChevronDown className="h-3 w-3 text-cyan-400" />
                          )
                        ) : (
                          <ChevronsUpDown className="h-3 w-3" />
                        )}
                      </span>
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/80">
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length} className="p-8 text-center text-slate-400 text-xs">
                  No matching intelligence records found in database.
                </td>
              </tr>
            ) : (
              paginatedData.map((row, rIndex) => (
                <tr
                  key={rIndex}
                  onClick={() => onRowClick && onRowClick(row)}
                  className={cn(
                    'transition-colors hover:bg-slate-800/50',
                    onRowClick && 'cursor-pointer'
                  )}
                >
                  {columns.map((col, cIndex) => (
                    <td key={cIndex} className={cn('p-3 text-slate-300', col.className)}>
                      {col.cell
                        ? col.cell(row)
                        : col.accessorKey
                        ? String(row[col.accessorKey] ?? '')
                        : null}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="flex items-center justify-between text-xs text-slate-400 px-1">
        <div>
          Showing <span className="text-slate-200">{filteredData.length === 0 ? 0 : (currentPage - 1) * pageSize + 1}</span> to{' '}
          <span className="text-slate-200">{Math.min(currentPage * pageSize, filteredData.length)}</span> of{' '}
          <span className="text-slate-200">{filteredData.length}</span> entries
        </div>
        <div className="flex items-center space-x-1.5">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
            disabled={currentPage === 1}
            className="h-7 px-2"
          >
            <ChevronLeft className="h-3.5 w-3.5" />
          </Button>
          <span className="px-2 text-slate-300">
            Page {currentPage} of {totalPages}
          </span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
            disabled={currentPage === totalPages || totalPages === 0}
            className="h-7 px-2"
          >
            <ChevronRight className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useRef, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { 
  ZoomIn, 
  ZoomOut, 
  RotateCcw, 
  Filter, 
  Layers, 
  User, 
  Building2, 
  Smartphone, 
  Landmark, 
  Home, 
  Truck, 
  ShieldAlert, 
  ExternalLink,
  SlidersHorizontal,
  X
} from 'lucide-react'
import { NetworkGraphData, GraphNode, GraphEdge, EntityType } from '../../types'
import { Button } from '../ui/button'
import { Badge } from '../ui/badge'
import { Card } from '../ui/card'
import { cn } from '../../lib/utils'

interface NetworkGraphContainerProps {
  initialData: NetworkGraphData
  height?: string
  onNodeClick?: (node: GraphNode) => void
  interactive?: boolean
}

export const NetworkGraphContainer: React.FC<NetworkGraphContainerProps> = ({
  initialData,
  height = 'h-[620px]',
  onNodeClick,
  interactive = true,
}) => {
  const navigate = useNavigate()
  const containerRef = useRef<HTMLDivElement>(null)

  // Viewport State
  const [zoom, setZoom] = useState(1)
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })

  // Selection & Hover
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null)
  const [hoveredNode, setHoveredNode] = useState<GraphNode | null>(null)

  // Filters
  const [minRiskScore, setMinRiskScore] = useState(0)
  const [selectedTypes, setSelectedTypes] = useState<EntityType[]>([
    'suspect', 'shell_company', 'burner_phone', 'bank_account', 'safehouse', 'vehicle', 'organization'
  ])
  const [showOnlySuspiciousEdges, setShowOnlySuspiciousEdges] = useState(false)
  const [showFilterDrawer, setShowFilterDrawer] = useState(false)

  // Filtered Nodes and Edges
  const filteredNodes = useMemo(() => {
    return initialData.nodes.filter(
      (node) => node.riskScore >= minRiskScore && selectedTypes.includes(node.type)
    )
  }, [initialData.nodes, minRiskScore, selectedTypes])

  const filteredNodeIds = useMemo(() => new Set(filteredNodes.map(n => n.id)), [filteredNodes])

  const filteredEdges = useMemo(() => {
    return initialData.edges.filter((edge) => {
      const hasBothNodes = filteredNodeIds.has(edge.source) && filteredNodeIds.has(edge.target)
      if (!hasBothNodes) return false
      if (showOnlySuspiciousEdges && !edge.isSuspicious) return false
      return true
    })
  }, [initialData.edges, filteredNodeIds, showOnlySuspiciousEdges])

  // Mouse wheel zoom
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault()
    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9
    setZoom((prev) => Math.min(Math.max(prev * zoomFactor, 0.4), 2.5))
  }

  // Pan handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return // Only primary button
    setIsDraggingCanvas(true)
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y })
  }

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y,
      })
    }
  }

  const handleMouseUp = () => {
    setIsDraggingCanvas(false)
  }

  const handleResetView = () => {
    setZoom(1)
    setPan({ x: 0, y: 0 })
  }

  const toggleTypeFilter = (type: EntityType) => {
    setSelectedTypes(prev => 
      prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type]
    )
  }

  // Helper icons and colors by entity type
  const getTypeMeta = (type: EntityType) => {
    switch (type) {
      case 'suspect':
        return { color: '#ef4444', label: 'Suspect', icon: User, stroke: 'rgba(239, 68, 68, 0.4)' }
      case 'shell_company':
        return { color: '#f59e0b', label: 'Shell Corp', icon: Building2, stroke: 'rgba(245, 158, 11, 0.4)' }
      case 'burner_phone':
        return { color: '#00e5ff', label: 'Burner Phone', icon: Smartphone, stroke: 'rgba(0, 229, 255, 0.4)' }
      case 'bank_account':
        return { color: '#10b981', label: 'Bank Account', icon: Landmark, stroke: 'rgba(16, 185, 129, 0.4)' }
      case 'safehouse':
        return { color: '#a855f7', label: 'Safehouse', icon: Home, stroke: 'rgba(168, 85, 247, 0.4)' }
      case 'vehicle':
        return { color: '#38bdf8', label: 'Vehicle', icon: Truck, stroke: 'rgba(56, 189, 248, 0.4)' }
      default:
        return { color: '#94a3b8', label: 'Entity', icon: User, stroke: 'rgba(148, 163, 184, 0.4)' }
    }
  }

  // Find node coordinates map
  const nodeMap = useMemo(() => {
    const map = new Map<string, GraphNode>()
    filteredNodes.forEach(n => map.set(n.id, n))
    return map
  }, [filteredNodes])

  return (
    <div className={cn('relative w-full rounded-sm border border-slate-800 bg-[#090d16] overflow-hidden select-none', height)}>
      {/* Background Tactical Grid & Radar Concentrics */}
      <div className="absolute inset-0 pointer-events-none tactical-grid opacity-60" />
      <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-20">
        <circle cx="50%" cy="50%" r="150" fill="none" stroke="#00e5ff" strokeWidth="1" strokeDasharray="4 4" />
        <circle cx="50%" cy="50%" r="300" fill="none" stroke="#00e5ff" strokeWidth="1" strokeDasharray="4 4" />
        <circle cx="50%" cy="50%" r="450" fill="none" stroke="#00e5ff" strokeWidth="1" strokeDasharray="4 4" />
        <line x1="50%" y1="0" x2="50%" y2="100%" stroke="#00e5ff" strokeWidth="0.5" strokeDasharray="2 2" />
        <line x1="0" y1="50%" x2="100%" y2="50%" stroke="#00e5ff" strokeWidth="0.5" strokeDasharray="2 2" />
      </svg>

      {/* Top Left Toolbar */}
      <div className="absolute left-3 top-3 z-10 flex items-center space-x-2">
        <div className="flex items-center space-x-1 rounded-sm border border-slate-800 bg-[#0c121e]/90 p-1 backdrop-blur-md">
          <Button variant="ghost" size="sm" onClick={() => setZoom(z => Math.min(z * 1.2, 2.5))} title="Zoom In">
            <ZoomIn className="h-3.5 w-3.5" />
          </Button>
          <Button variant="ghost" size="sm" onClick={() => setZoom(z => Math.max(z / 1.2, 0.4))} title="Zoom Out">
            <ZoomOut className="h-3.5 w-3.5" />
          </Button>
          <Button variant="ghost" size="sm" onClick={handleResetView} title="Reset Center">
            <RotateCcw className="h-3.5 w-3.5" />
          </Button>
          <div className="h-4 w-px bg-slate-800 mx-1" />
          <span className="font-mono text-[10px] text-cyan-400 px-2">
            {Math.round(zoom * 100)}%
          </span>
        </div>

        <Button
          variant={showFilterDrawer ? 'cyan' : 'tactical'}
          size="sm"
          onClick={() => setShowFilterDrawer(!showFilterDrawer)}
          className="flex items-center space-x-1.5"
        >
          <Filter className="h-3.5 w-3.5" />
          <span>Filters ({filteredNodes.length}/{initialData.nodes.length})</span>
        </Button>
      </div>

      {/* Top Right Intelligence Telemetry */}
      <div className="absolute right-3 top-3 z-10 flex items-center space-x-2">
        <div className="hidden sm:flex items-center space-x-2 rounded-sm border border-slate-800 bg-[#0c121e]/90 px-3 py-1.5 font-mono text-[10px] text-slate-400 backdrop-blur-md">
          <span className="flex items-center space-x-1">
            <span className="h-2 w-2 rounded-full bg-cyan-400 animate-pulse" />
            <span className="text-cyan-300 font-semibold">SYNAPSE TOPOLOGY ENGINE</span>
          </span>
          <span>•</span>
          <span>NODES: <span className="text-slate-200">{filteredNodes.length}</span></span>
          <span>•</span>
          <span>EDGES: <span className="text-slate-200">{filteredEdges.length}</span></span>
        </div>
      </div>

      {/* Filter Drawer Overlay */}
      {showFilterDrawer && (
        <div className="absolute left-3 top-14 z-20 w-72 rounded-sm border border-slate-700 bg-[#0c121e]/95 p-4 shadow-2xl backdrop-blur-md font-mono text-xs">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-3">
            <span className="font-bold text-cyan-400 flex items-center gap-1.5">
              <SlidersHorizontal className="h-3.5 w-3.5" />
              TOPOLOGY FILTERS
            </span>
            <button onClick={() => setShowFilterDrawer(false)} className="text-slate-400 hover:text-white">
              <X className="h-3.5 w-3.5" />
            </button>
          </div>

          <div className="space-y-4">
            {/* Risk Threshold */}
            <div>
              <div className="flex justify-between text-[11px] text-slate-300 mb-1">
                <span>Threat Risk Threshold</span>
                <span className="text-cyan-400 font-bold">{minRiskScore}+</span>
              </div>
              <input
                type="range"
                min="0"
                max="95"
                step="5"
                value={minRiskScore}
                onChange={(e) => setMinRiskScore(Number(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-400"
              />
            </div>

            {/* Entity Types */}
            <div>
              <div className="text-[11px] text-slate-300 mb-2 font-semibold">Entity Classes</div>
              <div className="grid grid-cols-2 gap-1.5">
                {(['suspect', 'shell_company', 'burner_phone', 'bank_account', 'safehouse', 'vehicle'] as EntityType[]).map((type) => {
                  const meta = getTypeMeta(type)
                  const isChecked = selectedTypes.includes(type)
                  return (
                    <button
                      key={type}
                      onClick={() => toggleTypeFilter(type)}
                      className={cn(
                        'flex items-center space-x-1.5 px-2 py-1 rounded-xs border text-[10px] text-left transition-colors',
                        isChecked 
                          ? 'border-cyan-500/50 bg-cyan-950/40 text-cyan-200' 
                          : 'border-slate-800 bg-slate-900/60 text-slate-400 opacity-60'
                      )}
                    >
                      <meta.icon className="h-3 w-3" style={{ color: meta.color }} />
                      <span className="truncate">{meta.label}</span>
                    </button>
                  )
                })}
              </div>
            </div>

            {/* Suspicious Only */}
            <label className="flex items-center space-x-2 text-[11px] text-slate-300 cursor-pointer pt-1 border-t border-slate-800">
              <input
                type="checkbox"
                checked={showOnlySuspiciousEdges}
                onChange={(e) => setShowOnlySuspiciousEdges(e.target.checked)}
                className="rounded-xs border-slate-700 bg-slate-900 text-cyan-500 focus:ring-0"
              />
              <span>Highlight Suspicious Transfers Only</span>
            </label>
          </div>
        </div>
      )}

      {/* Main Interactive SVG Canvas */}
      <div
        ref={containerRef}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        className="w-full h-full cursor-grab active:cursor-grabbing"
      >
        <svg className="w-full h-full overflow-visible">
          <g transform={`translate(${pan.x + 80}, ${pan.y + 40}) scale(${zoom})`}>
            {/* Edges */}
            {filteredEdges.map((edge) => {
              const src = nodeMap.get(edge.source)
              const tgt = nodeMap.get(edge.target)
              if (!src || !tgt || src.x === undefined || src.y === undefined || tgt.x === undefined || tgt.y === undefined) return null

              const isHighlighted = 
                selectedNode && (selectedNode.id === edge.source || selectedNode.id === edge.target)

              const isWire = edge.relationship === 'wire_transfer'
              const strokeColor = isHighlighted 
                ? '#00e5ff' 
                : isWire 
                ? '#10b981' 
                : edge.isSuspicious 
                ? '#ef4444' 
                : '#475e82'

              const midX = (src.x + tgt.x) / 2
              const midY = (src.y + tgt.y) / 2

              return (
                <g key={edge.id}>
                  {/* Glowing line for active connections */}
                  {isHighlighted && (
                    <line
                      x1={src.x}
                      y1={src.y}
                      x2={tgt.x}
                      y2={tgt.y}
                      stroke="#00e5ff"
                      strokeWidth="4"
                      strokeOpacity="0.4"
                    />
                  )}
                  <line
                    x1={src.x}
                    y1={src.y}
                    x2={tgt.x}
                    y2={tgt.y}
                    stroke={strokeColor}
                    strokeWidth={isHighlighted ? 2.5 : Math.max(edge.weight / 4, 1.2)}
                    strokeDasharray={edge.relationship === 'encrypted_call' ? '4 4' : undefined}
                    strokeOpacity={isHighlighted ? 1 : 0.75}
                  />

                  {/* Edge Label Pill */}
                  {(zoom > 0.75 || isHighlighted) && (
                    <g transform={`translate(${midX}, ${midY})`}>
                      <rect
                        x="-45"
                        y="-8"
                        width="90"
                        height="16"
                        rx="2"
                        fill="#0c121e"
                        stroke={strokeColor}
                        strokeWidth="0.8"
                        fillOpacity="0.9"
                      />
                      <text
                        textAnchor="middle"
                        y="3.5"
                        fill="#cbd5e1"
                        fontSize="7.5"
                        fontFamily="monospace"
                        fontWeight="600"
                      >
                        {edge.amount || edge.label.slice(0, 15)}
                      </text>
                    </g>
                  )}
                </g>
              )
            })}

            {/* Nodes */}
            {filteredNodes.map((node) => {
              if (node.x === undefined || node.y === undefined) return null

              const meta = getTypeMeta(node.type)
              const isSelected = selectedNode?.id === node.id
              const isHovered = hoveredNode?.id === node.id
              const nodeRadius = node.isHVT ? 26 : 20

              return (
                <g
                  key={node.id}
                  transform={`translate(${node.x}, ${node.y})`}
                  className="cursor-pointer transition-transform"
                  onClick={(e) => {
                    e.stopPropagation()
                    setSelectedNode(node)
                    if (onNodeClick) onNodeClick(node)
                  }}
                  onMouseEnter={() => setHoveredNode(node)}
                  onMouseLeave={() => setHoveredNode(null)}
                >
                  {/* Outer Radar Glow on Selected / HVT */}
                  {(isSelected || node.isHVT) && (
                    <circle
                      r={nodeRadius + 8}
                      fill="none"
                      stroke={meta.color}
                      strokeWidth="1.5"
                      strokeDasharray="3 3"
                      className="animate-spin-slow"
                      opacity="0.8"
                    />
                  )}

                  {/* Base Circle */}
                  <circle
                    r={nodeRadius}
                    fill="#0a0f1d"
                    stroke={isSelected ? '#00e5ff' : meta.color}
                    strokeWidth={isSelected ? 3 : 2}
                  />

                  {/* Threat Risk Pill Badge at top of node */}
                  <g transform={`translate(0, -${nodeRadius + 4})`}>
                    <rect
                      x="-14"
                      y="-7"
                      width="28"
                      height="12"
                      rx="2"
                      fill={node.riskScore >= 90 ? '#ef4444' : node.riskScore >= 75 ? '#f59e0b' : '#00e5ff'}
                    />
                    <text
                      textAnchor="middle"
                      y="2"
                      fill="#000000"
                      fontSize="7"
                      fontWeight="bold"
                      fontFamily="monospace"
                    >
                      {node.riskScore}
                    </text>
                  </g>

                  {/* Center Symbol / Icon Text */}
                  <text
                    textAnchor="middle"
                    y="4"
                    fill={meta.color}
                    fontSize={node.isHVT ? "12" : "10"}
                    fontWeight="bold"
                    fontFamily="monospace"
                  >
                    {node.type === 'suspect' ? 'SUS' : 
                     node.type === 'shell_company' ? 'CORP' : 
                     node.type === 'burner_phone' ? 'SIG' : 
                     node.type === 'bank_account' ? 'IBAN' : 
                     node.type === 'safehouse' ? 'SAFE' : 'VEH'}
                  </text>

                  {/* Label Text below node */}
                  <text
                    textAnchor="middle"
                    y={nodeRadius + 14}
                    fill={isSelected ? '#00e5ff' : '#f1f5f9'}
                    fontSize="9.5"
                    fontFamily="monospace"
                    fontWeight="600"
                    className="select-none filter drop-shadow-[0_2px_4px_rgba(0,0,0,0.9)]"
                  >
                    {node.label.length > 20 ? node.label.slice(0, 18) + '...' : node.label}
                  </text>
                </g>
              )
            })}
          </g>
        </svg>
      </div>

      {/* Selected Node Intelligence Inspector Panel (Right Drawer) */}
      {selectedNode && (
        <div className="absolute right-3 bottom-3 top-14 z-20 w-84 rounded-sm border border-cyan-500/50 bg-[#0c121e]/95 p-4 shadow-2xl backdrop-blur-lg font-mono text-xs animate-in slide-in-from-right duration-150 overflow-y-auto">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-3">
            <div className="flex items-center space-x-2">
              <span className="h-2 w-2 rounded-full bg-cyan-400" />
              <span className="font-bold text-cyan-400 tracking-wider">TARGET DOSSIER TELEMETRY</span>
            </div>
            <button 
              onClick={() => setSelectedNode(null)}
              className="rounded-xs p-1 text-slate-400 hover:text-white hover:bg-slate-800"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          </div>

          <div className="space-y-3">
            {/* Header info */}
            <div>
              <div className="flex items-center justify-between">
                <Badge variant={selectedNode.riskScore >= 90 ? 'critical' : 'high'}>
                  RISK INDEX {selectedNode.riskScore}/100
                </Badge>
                <span className="text-[10px] text-slate-400 uppercase">{selectedNode.type}</span>
              </div>
              <h3 className="mt-1.5 text-sm font-bold text-slate-100">{selectedNode.label}</h3>
              <p className="text-[10px] text-cyan-300">Cluster: {selectedNode.cluster} Division</p>
            </div>

            {/* Metrics grid */}
            <div className="grid grid-cols-2 gap-2 border-y border-slate-800 py-2.5 text-[10px]">
              <div>
                <span className="text-slate-400">Node Degree:</span>
                <span className="ml-1 text-slate-200 font-bold">{selectedNode.degree} links</span>
              </div>
              <div>
                <span className="text-slate-400">Betweenness:</span>
                <span className="ml-1 text-slate-200 font-bold">{selectedNode.betweenness}</span>
              </div>
              <div>
                <span className="text-slate-400">Legal Status:</span>
                <span className="ml-1 text-amber-400 font-bold">{selectedNode.status}</span>
              </div>
              <div>
                <span className="text-slate-400">Classification:</span>
                <span className="ml-1 text-red-400 font-bold">{selectedNode.isHVT ? 'HVT TIER-1' : 'TIER-2'}</span>
              </div>
            </div>

            {/* Connected Relationships */}
            <div>
              <div className="text-[10px] uppercase tracking-wider text-slate-400 font-semibold mb-1.5">
                Active Direct Vectors ({initialData.edges.filter(e => e.source === selectedNode.id || e.target === selectedNode.id).length})
              </div>
              <div className="space-y-1 max-h-32 overflow-y-auto">
                {initialData.edges
                  .filter(e => e.source === selectedNode.id || e.target === selectedNode.id)
                  .map(edge => {
                    const peerId = edge.source === selectedNode.id ? edge.target : edge.source
                    const peer = initialData.nodes.find(n => n.id === peerId)
                    return (
                      <div key={edge.id} className="p-1.5 rounded-xs bg-slate-900/90 border border-slate-800 text-[10px] flex items-center justify-between">
                        <div>
                          <div className="text-slate-200 font-semibold truncate w-40">{peer?.label}</div>
                          <div className="text-slate-400 text-[9px]">{edge.label}</div>
                        </div>
                        {edge.amount && (
                          <span className="text-emerald-400 font-bold">{edge.amount}</span>
                        )}
                      </div>
                    )
                  })}
              </div>
            </div>

            {/* Drill Down Action */}
            <div className="pt-2">
              <Button
                variant="cyan"
                size="sm"
                className="w-full flex items-center justify-center space-x-1"
                onClick={() => {
                  if (selectedNode.type === 'suspect' || selectedNode.id.startsWith('ent-')) {
                    navigate(`/entity/${selectedNode.id}`)
                  } else {
                    navigate(`/cases`)
                  }
                }}
              >
                <span>Open Complete Dossier</span>
                <ExternalLink className="h-3 w-3 ml-1" />
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Legend Footer */}
      <div className="absolute left-3 bottom-3 z-10 hidden md:flex items-center space-x-3 rounded-sm border border-slate-800/80 bg-[#0c121e]/90 px-3 py-1.5 font-mono text-[9px] text-slate-400 backdrop-blur-md">
        <span className="font-semibold text-slate-300 uppercase">Legend:</span>
        <span className="flex items-center space-x-1">
          <span className="h-2 w-2 rounded-full bg-red-500" />
          <span>Suspect</span>
        </span>
        <span className="flex items-center space-x-1">
          <span className="h-2 w-2 rounded-full bg-amber-500" />
          <span>Shell Company</span>
        </span>
        <span className="flex items-center space-x-1">
          <span className="h-2 w-2 rounded-full bg-cyan-400" />
          <span>Burner SIGINT</span>
        </span>
        <span className="flex items-center space-x-1">
          <span className="h-2 w-2 rounded-full bg-emerald-500" />
          <span>Financial / Wire</span>
        </span>
        <span className="flex items-center space-x-1">
          <span className="h-2 w-2 rounded-full bg-purple-500" />
          <span>Safehouse</span>
        </span>
      </div>
    </div>
  )
}

import React, { useState } from 'react'
import { 
  Share2, 
  Download, 
  Layers, 
  Filter, 
  RefreshCw, 
  ShieldAlert, 
  Search, 
