  Route,
  Zap,
  Info
} from 'lucide-react'
import { mockNetworkGraph, mockEntities } from '../data/mockData'
import { NetworkGraphContainer } from '../components/network/NetworkGraphContainer'
import { Button } from '../components/ui/button'
import { Badge } from '../components/ui/badge'
import { Card, CardContent } from '../components/ui/card'

export const NetworkAnalysisPage: React.FC = () => {
  const [selectedLayout, setSelectedLayout] = useState<'force' | 'cluster' | 'financial'>('force')
  const [pathfinderOpen, setPathfinderOpen] = useState(false)
  const [sourceNode, setSourceNode] = useState('ent-1')
  const [targetNode, setTargetNode] = useState('ent-8')
  const [pathResult, setPathResult] = useState<string[] | null>(null)

  const handleRunPathfinder = () => {
    // Simulated shortest path between Viktor Ramos (ent-1) and Zurich Acct (ent-8)
    setPathResult([
      'Viktor Ramos (Leader)',
      'Elena Rostova (Financier)',
      'Aethelgard Holdings SA (Shell)',
      'Zurich Acct #CH-882-99 (Settlement)'
    ])
  }

  const handleExport = (format: string) => {
    alert(`Exporting topology graph in format: ${format.toUpperCase()} (FIPS-140 Compliant Bundle)`)
  }

  return (
    <div className="space-y-4 font-mono">
      {/* Top Header & Intelligence Workbench Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-3 border-b border-slate-800 pb-3">
        <div>
          <div className="flex items-center space-x-2">
            <Share2 className="h-6 w-6 text-cyan-400" />
            <h1 className="text-xl md:text-2xl font-black tracking-tight text-slate-100">
              SYNAPSE TOPOLOGY & NETWORK ANALYSIS
            </h1>
            <Badge variant="cyan">NEURAL CLUSTERING</Badge>
          </div>
          <p className="text-xs text-slate-400 mt-0.5">
            Cross-entity link analysis, financial transaction flow mapping & shortest-path correlation
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          {/* Layout Presets */}
          <div className="flex items-center space-x-1 rounded bg-slate-900 border border-slate-800 p-1 text-xs">
            <span className="text-[10px] text-slate-400 px-1 uppercase">Layout:</span>
            <button
              onClick={() => setSelectedLayout('force')}
              className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold transition-colors ${
                selectedLayout === 'force' ? 'bg-cyan-950 text-cyan-300 border border-cyan-700' : 'text-slate-400 hover:text-white'
              }`}
            >
              Force-Directed
            </button>
            <button
              onClick={() => setSelectedLayout('cluster')}
              className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold transition-colors ${
                selectedLayout === 'cluster' ? 'bg-cyan-950 text-cyan-300 border border-cyan-700' : 'text-slate-400 hover:text-white'
              }`}
            >
              Syndicate Cluster
            </button>
            <button
              onClick={() => setSelectedLayout('financial')}
              className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold transition-colors ${
                selectedLayout === 'financial' ? 'bg-cyan-950 text-cyan-300 border border-cyan-700' : 'text-slate-400 hover:text-white'
              }`}
            >
              Financial Hierarchy
            </button>
          </div>

          {/* Pathfinder Trigger */}
          <Button
            variant={pathfinderOpen ? 'cyan' : 'tactical'}
            size="sm"
            onClick={() => setPathfinderOpen(!pathfinderOpen)}
            className="flex items-center space-x-1.5"
          >
            <Route className="h-3.5 w-3.5" />
            <span>Pathfinder</span>
          </Button>

          {/* Export Dropdown */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => handleExport('json')}
            className="flex items-center space-x-1.5"
          >
            <Download className="h-3.5 w-3.5" />
            <span>Export</span>
          </Button>
        </div>
      </div>

      {/* Pathfinder Subpanel */}
      {pathfinderOpen && (
        <Card className="bg-[#0c121e] border-cyan-500/50 p-3">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-3 text-xs">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-cyan-400 font-bold flex items-center gap-1">
                <Zap className="h-3.5 w-3.5 text-cyan-400" />
                SHORTEST ATTRIBUTION PATH:
              </span>
              <div className="flex items-center space-x-1">
                <span className="text-slate-400 text-[10px]">Source:</span>
                <select
                  value={sourceNode}
                  onChange={(e) => setSourceNode(e.target.value)}
                  className="rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-200 text-xs"
                >
                  {mockEntities.map(e => (
                    <option key={e.id} value={e.id}>{e.name}</option>
                  ))}
                </select>
              </div>
              <span className="text-slate-400">➔</span>
              <div className="flex items-center space-x-1">
                <span className="text-slate-400 text-[10px]">Target:</span>
                <select
                  value={targetNode}
                  onChange={(e) => setTargetNode(e.target.value)}
                  className="rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-200 text-xs"
                >
                  {mockEntities.map(e => (
                    <option key={e.id} value={e.id}>{e.name}</option>
                  ))}
                </select>
              </div>
              <Button variant="cyan" size="sm" onClick={handleRunPathfinder} className="h-7 text-[10px]">
                Compute Vector Path
              </Button>
            </div>

            {pathResult && (
              <div className="flex items-center space-x-1 text-[11px] text-emerald-400 font-bold">
                <span>Direct Hops (3):</span>
                <span className="text-slate-200">{pathResult.join(' ➔ ')}</span>
              </div>
            )}
          </div>
        </Card>
      )}

      {/* Main Graph Interactive Container */}
      <NetworkGraphContainer
        initialData={mockNetworkGraph}
        height="h-[calc(100vh-210px)] min-h-[580px]"
      />
    </div>
  )
}

